let devView=new URLSearchParams(location.search).get('view')||'explorer',devQuery='',devTypes=new Set(['songs','artists','albums','tags']),devLimits={songs:10,artists:10,albums:10,tags:10},tableQuery='',tableFilters={},tablePage=0,tableSort='id',tableDir=1,importQuery='',keepImport=true,imported=new Set(),importRows=[];
