const tableColumns={songs:[['id','ID'],['cover_url','Cover'],['name','Title'],['artist','Artists'],['album','Album'],['tag_names','Tags'],['elo_score','Elo'],['matches_played','Matches'],['track_number','Track'],['preview','Preview']],artists:[['id','ID'],['cover_url','Cover'],['name','Artist'],['song_count','Songs'],['score','Impact'],['avg_elo','Avg Elo']],albums:[['id','ID'],['cover_url','Cover'],['name','Album / release'],['release_date','Released'],['song_count','Songs'],['score','Impact'],['avg_elo','Avg Elo'],['release_type','Type']],tags:[['id','ID'],['name','Tag'],['song_count','Songs'],['score','Impact'],['avg_elo','Avg Elo']]};
let visibleColumns={};try{visibleColumns=JSON.parse(localStorage.getItem('tableColumns')||'{}')}catch{}
