function editorError(message){const node=$('#editor-error');if(node){node.textContent=message;node.hidden=false;node.focus()}else toast(message)}
async function saveEdit(values){const {type,id}=editTarget;const payload={...values,artist:values.artists,genres:values.tags};try{await api(`/api/dev/edit_${{songs:'song',artists:'artist',albums:'album',tags:'genre'}[type]}/${id}`,payload);await refreshData();editTarget=null;dialog.close();renderDevView();toast('Saved')}catch(error){editorError(error.message)}}
async function tool(name){editTarget=null;toolTarget={name};const routes={'Trivia':'/trivia','Tournament':'/tournament','Global stats':'/global_stats','Tournament archive':'/tournament_stats','Lock database':'/dev/logout'};if(routes[name]){location.href=routes[name];return}if(name==='Apple Music'){devView='import';renderDevView();return}
 if(['Manual Elo correction','Trivia maintenance'].includes(name)){if(!songs.length){toast('No songs');return}openDialog(name,maintenancePicker()+(name==='Manual Elo correction'?field('elo','New Elo','','number','required min="0" max="5000"'):field('attempts','Attempts','','number','required min="0"')+field('correct','Correct points','','number','required min="0"')+'<button class="btn small danger" type="button" data-clear-trivia disabled>Clear Stats</button>'));$('#editor-submit').disabled=true;renderMaintenanceMatches();$('#maintenance-query').focus();return}

 try{
 if(name==='Create backup'){const result=await api('/api/dev/backup',{});toast('Backup: '+result.backup);return}
 if(name==='Export snapshot'){const result=await api('/api/dev/export',{});toast(result.message);return}
 if(name==='Sync database'){openDialog(name,'<p>Push the database snapshot to the configured Git remote?</p>','Sync');return}
 if(name==='Restore backup'){const data=await api('/api/dev/overview');openDialog(name,`<div class="field"><label for="backup-select">Backup</label><select id="backup-select" name="filename">${data.backups.map(b=>`<option>${esc(b.name)}</option>`).join('')}</select></div>`,'Restore');return}
 if(name==='Reset competition'){const data=await api('/api/dev/reset-preview');openDialog(name,`<div class="health-row"><span>Votes / trivia / tournaments</span><strong>${data.clear.votes_and_history} / ${data.clear.trivia_stats} / ${data.clear.tournaments}</strong></div>`+field('confirmation','Type RESET COMPETITION',''),'Back up & reset');return}
 if(name==='Database overview'){const data=await api('/api/dev/overview');openDialog(name,Object.entries(data.counts).map(([key,value])=>`<div class="health-row"><span>${esc(key)}</span><strong>${value}</strong></div>`).join(''),'Done');return}
 if(name==='Database integrity'){const data=await api('/api/dev/integrity');openDialog(name,`<div class="health-row"><span>SQLite</span><strong>${esc(data.integrity.join(', '))}</strong></div><div class="health-row"><span>Foreign-key errors</span><strong>${data.foreign_key_errors.length}</strong></div><div class="health-row"><span>Track-number conflicts</span><strong>${data.track_number_conflicts.length}</strong></div>${data.track_number_conflicts.map(s=>`<div class="health-row track-conflict"><div><strong>${esc(s.title)}</strong><small>${esc(s.album||'No album')} · track ${esc(s.track_number)} · ${esc(s.issue)}</small></div><button class="btn small" type="button" data-edit="songs" data-id="${s.id}">Edit</button></div>`).join('')}`,'Done');return}
 if(name==='Duplicate finder'){const groups=new Map();songs.forEach(s=>{const key=normal(s.title+' '+s.artist);groups.set(key,(groups.get(key)||[]).concat(s))});const duplicates=[...groups.values()].filter(g=>g.length>1);openDialog(name,duplicates.length?duplicates.map(g=>`<div class="health-row"><strong>${esc(g[0].title)}</strong><span>${g.map(s=>'#'+s.id).join(', ')}</span></div>`).join(''):'<div class="empty">No exact title / artist duplicates</div>','Done');return}
 }catch(error){toast(error.message)}
}
function deleteRecord(type,id){const r=byId(records(type),id);editTarget=null;toolTarget={name:'delete',type,id:Number(id)};openDialog('Delete '+label(type),`<strong>${esc(r.name)}</strong>`,'Delete')}
async function deleteLocal(type,id){try{await api(`/api/dev/delete_${{songs:'song',artists:'artist',albums:'album',tags:'genre'}[type]}/${id}`,null,'DELETE');await refreshData();renderDevView();dialog.close();toast('Deleted')}catch(error){toast(error.message)}}
// Real HTTP actions. All writes refresh the catalogue from the database.
async function api(url,data,method){const response=await fetch(url,{method:method||(data!==undefined?'POST':'GET'),headers:data!==undefined?{'Content-Type':'application/json'}:{},body:data!=null?JSON.stringify(data):undefined});let result;try{result=await response.json()}catch{throw new Error(response.redirected?'Sign in to the dev dashboard':'Request failed ('+response.status+')')}if(!response.ok)throw new Error(result.message||result.error||'Request failed');return result}
async function refreshData(){const fresh=await api('/api/collection');Object.assign(DB,fresh);rebuild()}
async function updateHealth(){try{const data=await api('/api/dev/overview');if($('#health-integrity'))$('#health-integrity').textContent=data.integrity;if($('#health-fk'))$('#health-fk').textContent=data.foreign_key_errors}catch(error){toast(error.message)}}
async function importSong(id){const row=byId(importRows,id);if(!row)return;const button=$(`[data-import="${id}"]`);button.disabled=true;try{await api('/api/dev/add_song',row);imported.add(id);await refreshData();if(keepImport)renderAppleResults();else{importQuery='';importRows=[];$('#apple-query').value='';renderAppleResults()}toast('Added')}catch(error){toast(error.message);button.disabled=false}}
async function submitTool(values){const name=toolTarget?.name;let result;
 if(name==='delete'){await deleteLocal(toolTarget.type,toolTarget.id);return}
 if(name==='Delete tournament'){result=await api('/api/dev/tournaments/'+toolTarget.id,null,'DELETE')}
 else if(name==='Manual Elo correction'){result=await api('/api/dev/elo-correction',{song_id:values.song_id,new_elo:values.elo})}
 else if(name==='Trivia maintenance'){result=await api('/api/dev/trivia/'+values.song_id,{attempts:values.attempts,correct:values.correct})}
 else if(name==='Restore backup'){result=await api('/api/dev/restore-backup',{filename:values.filename})}
 else if(name==='Reset competition'){result=await api('/api/dev/reset-database',{confirmation:values.confirmation})}
 else if(name==='Sync database'){result=await api('/api/dev/sync',{})}
 else {dialog.close();return}
 await refreshData();dialog.close();if(page==='dev')renderDevView();toast(result.message||'Saved');
}
// V3.1 collection profiles share the song page's layout and player controls.
let profileState=null,albumPlayer=null;
const trackOrder=(a,b)=>(a.track_number||Infinity)-(b.track_number||Infinity)||a.id-b.id;
function compactArt(s,type='songs'){return `<span class="small-art ${type==='artists'?'circle':''}" aria-hidden="true">♫${s.cover_url?`<img src="${esc(s.cover_url)}" alt="" loading="lazy" onerror="this.hidden=true">`:''}</span>`}
function profileTags(tracks,excludeId=null){return [...new Set(tracks.flatMap(s=>s.tag_ids))].map(id=>byId(tags,id)).filter(t=>t&&t.id!==excludeId).sort((a,b)=>a.name.localeCompare(b.name)).map(t=>`<a class="badge tag" href="${urlFor('tags',t)}"># ${esc(t.name)}</a>`).join('')}
function renderProfile(){
 const info=JSON.parse($('#profile-data').textContent),type=info.kind,item=records(type).find(r=>normal(r.name)===normal(info.name));if(!item)throw new Error('Profile unavailable');
 const tracks=linkedSongs(type,item),isAlbum=type==='albums',isTag=type==='tags',kind=colour(type),sum=key=>tracks.reduce((n,s)=>n+Number(s[key]||0),0),ids=new Set(tracks.map(s=>s.id));
 profileState={type,item,tracks,sort:'rank'};
 const entries=DB.tournament_entries.filter(e=>ids.has(e.song_id)),wins=DB.tournament_matches.filter(m=>m.status==='completed'&&ids.has(m.winner_id)),losses=DB.tournament_matches.filter(m=>m.status==='completed'&&ids.has(m.loser_id)),titles=DB.tournaments.filter(t=>t.status==='completed'&&ids.has(t.champion_id)),played=wins.length+losses.length;
 const artistIds=[...new Set(tracks.flatMap(s=>s.artist_ids))],artistLinks=artistIds.map(id=>byId(artists,id)).filter(Boolean).map(a=>`<a class="artist" href="${urlFor('artists',a)}">${esc(a.name)}</a>`).join('<span class="separator muted">,</span>');
 const properAlbums=albums.filter(a=>properAlbum(a)&&a.song_ids.some(id=>ids.has(id))),rank=records(type).filter(a=>(!isAlbum||properAlbum(a))&&a.score>item.score).length+1;
 const queue=[...tracks].filter(s=>s.audio_url).sort(trackOrder),attempts=sum('attempts'),correct=sum('correct'),recognition=attempts?Math.round(100*correct/(attempts*2)):null;
 const highlight=(s,title)=>s?`<a class="profile-highlight" href="${urlFor('songs',s)}">${compactArt(s)}<div><small>${title}</small><strong>${esc(s.title)}</strong><b>${Math.round(s.elo_score)} Elo</b></div></a>`:'';
 main.classList.add('narrow');
 main.innerHTML=`<section class="panel song-profile profile-${kind}"><div>${isAlbum?`<div class="album-cover-player"><button class="cover-button" data-audio="album-audio" data-album-play aria-label="Play album previews" aria-pressed="false" ${queue.length?'':'disabled'}>${artwork(item,'albums')}<span class="play-overlay" aria-hidden="true">▶</span></button>${queue.length?'<button class="album-cover-step previous" data-album-step="-1" aria-label="Previous album preview" title="Previous preview">‹</button><button class="album-cover-step next" data-album-step="1" aria-label="Next album preview" title="Next preview">›</button>':''}</div><audio id="album-audio" preload="none"></audio><div class="album-player-info" id="album-player-info" role="status">${queue.length?`${queue.length} previews · 10 seconds each`:'No audio previews'}</div>`:artwork(item,type)}</div><div><h1>${isTag?'# ':''}${esc(item.name)}</h1><div class="metadata">${isAlbum?artistLinks:`${tracks.length} tracks ${isTag?`<span class="separator muted">·</span> ${artistIds.length} artists `:''} <span class="separator muted">·</span> ${properAlbums.length} albums`}</div><div class="tags">${profileTags(tracks,isTag?item.id:null)}</div><div class="profile-facts">${isAlbum&&item.release_date?`<span>Released <b>${esc(item.release_date.slice(0,10))}</b></span>`:''}<span>Previews <b>${queue.length} / ${tracks.length}</b></span><span>Voting matches <b>${sum('matches_played')}</b></span><span>Highest track peak <b>${tracks.length?Math.round(Math.max(...tracks.map(s=>s.highest_elo||s.elo_score))):'—'} Elo</b></span></div></div></section><div class="stats">${stat('Impact Score',Math.round(item.impact_score),kind)}${stat('Global Rank',isAlbum&&!properAlbum(item)?'—':'#'+rank,kind)}${stat('Average Elo',Math.round(item.avg_elo),kind)}${stat('Tracks',tracks.length,kind)}</div><div class="profile-highlights">${highlight(tracks[0],'Highest-ranked Track')}${highlight(tracks.at(-1),'Track to Rediscover')}</div><div class="song-sections"><section class="panel recognition-panel"><div class="section-head"><h2 class="recognition">Recognisability</h2><div class="profile-stat-links">${isAlbum||type==='artists'?`<a class="recognition" href="${performancePath(type)}?metric=recognition">Rankings ↗</a>`:''}<a class="recognition" href="/trivia_stats">Trivia stats ↗</a></div></div><div class="feature-row"><div><strong>${attempts} attempts</strong><p>${correct} / ${attempts*2} points · ${tracks.filter(s=>s.attempts>0).length} tested tracks</p></div><strong class="big recognition">${recognition===null?'Untested':recognition+'%'}</strong></div>${recognition===null?'':`<div class="progress"><span style="width:${Math.min(100,recognition)}%"></span></div>`}</section><section class="panel tournament-panel"><div class="section-head"><h2 class="tournament">Tournament Record</h2><div class="profile-stat-links">${isAlbum||type==='artists'?`<a class="tournament" href="${performancePath(type)}?metric=championships">Rankings ↗</a>`:''}<a class="tournament" href="/tournament_stats">View brackets ↗</a></div></div><div class="mini-stats"><div><b>${new Set(entries.map(e=>e.tournament_id)).size}</b><small>Brackets · ${entries.length} track entries</small></div><div><b>${titles.length}</b><small>Championships</small></div><div><b>${played?Math.round(wins.length/played*100)+'%':'—'}</b><small>${wins.length}W · ${losses.length}L</small></div><div><b>${wins.reduce((n,m)=>n+Number(m.points_awarded||0),0).toFixed(2)}</b><small>Points</small></div></div></section>${!isAlbum&&properAlbums.length?`<section class="panel"><div class="section-head"><h2 class="album">Albums</h2></div><div class="profile-albums">${properAlbums.map(a=>`<a class="profile-album-card album" href="${urlFor('albums',a)}">${artwork(a,'albums')}<strong>${esc(a.title)}</strong><small>${a.song_count} tracks · ${Math.round(a.score)} impact${a.release_date?' · '+esc(a.release_date.slice(0,4)):''}</small></a>`).join('')}</div></section>`:''}<section class="panel"><div class="section-head"><h2 class="${kind}">${isAlbum?'Album Tracks':isTag?'Tagged Tracks':'Ranked Discography'}</h2>${isAlbum?'<div class="pill-nav" aria-label="Track order"><button class="pill active" data-profile-sort="rank" aria-pressed="true">Ranked</button><button class="pill" data-profile-sort="track" aria-pressed="false">Track order</button></div>':''}</div><div id="profile-tracks"></div></section></div>`;
 renderProfileTracks();attachPlayers();
 if(isAlbum){albumPlayer={queue,index:-1,advancing:false,failed:new Set(),finished:false};const audio=$('#album-audio');audio.addEventListener('timeupdate',()=>{if(!audio.paused&&audio.currentTime>=10)advanceAlbum(1)});audio.addEventListener('ended',()=>advanceAlbum(1));audio.addEventListener('error',()=>{if(albumPlayer.index>=0&&!albumPlayer.advancing){albumPlayer.failed.add(albumPlayer.index);startAlbumAt(albumPlayer.index+1,albumPlayer.playRequested)}});audio.addEventListener('play',()=>{$('[data-album-play]').setAttribute('aria-label','Pause album previews')});audio.addEventListener('pause',()=>{$('[data-album-play]').setAttribute('aria-label','Play album previews')})}
}
function renderProfileTracks(){const {type,tracks,sort}=profileState,rows=sort==='track'?[...tracks].sort(trackOrder):tracks;$('#profile-tracks').innerHTML=rows.map((s,i)=>`<div class="profile-track-row" data-profile-track="${s.id}"><span class="compact-rank">${sort==='track'?(s.track_number||'—'):i+1}</span>${compactArt(s)}<div class="compact-copy"><a class="song" href="${urlFor('songs',s)}">${esc(s.title)}</a><div class="metadata">${metadata(s)}</div></div><div class="compact-score song"><b>${Math.round(s.elo_score)}</b><small>Elo · ${s.matches_played} matches</small></div><button class="btn small" data-audio="track-audio-${s.id}" aria-label="Play ${esc(s.title)}" aria-pressed="false" ${s.audio_url?'':'disabled'}><span class="play-overlay">▶</span></button><audio id="track-audio-${s.id}" src="${esc(s.audio_url)}" preload="none"></audio></div>`).join('')||'<div class="empty">No linked tracks yet</div>';attachPlayers();markAlbumTrack()}
function markAlbumTrack(){if(!albumPlayer)return;const selected=albumPlayer.queue[albumPlayer.index];$$('[data-profile-track]').forEach(row=>row.classList.toggle('is-playing',!!selected&&Number(row.dataset.profileTrack)===selected.id&&!$('#album-audio').paused))}
function updateAlbumInfo(){const {queue,index}=albumPlayer,s=queue[index];$('#album-player-info').innerHTML=s?`<small>${index+1} / ${queue.length} · 10-second preview</small><a class="song" href="${urlFor('songs',s)}">${esc(s.title)}</a><small>${esc(s.artist)}</small>`:`${queue.length} previews · 10 seconds each`;markAlbumTrack()}
async function startAlbumAt(index,play=true,direction=1){
 if(!albumPlayer)return;const state=albumPlayer,audio=$('#album-audio');if(state.advancing){state.pending={index,play,direction};return}state.advancing=true;state.playRequested=play;
 try{
  audio.pause();const count=state.queue.length;
  for(let offset=0;offset<count;offset++){
   const i=((index+offset*direction)%count+count)%count;if(state.failed.has(i))continue;
   state.index=i;state.finished=false;audio.src=state.queue[i].audio_url;audio.currentTime=0;updateAlbumInfo();
   if(!play)return;$$('audio').forEach(a=>{if(a!==audio)a.pause()});audio.volume=volume;
   try{await audio.play();if(!state.playRequested||!audio.isConnected)audio.pause();markAlbumTrack();return}catch(error){if(error.name==='AbortError')return;if(error.name==='NotAllowedError'){state.playRequested=false;toast('Press the album cover to play');return}state.failed.add(i)}
  }
  state.index=-1;state.finished=true;state.playRequested=false;audio.pause();audio.removeAttribute('src');$('#album-player-info').textContent='No playable previews';markAlbumTrack();
 }finally{state.advancing=false;if(state.pending){const pending=state.pending;state.pending=null;await startAlbumAt(pending.index,pending.play,pending.direction)}}
}
async function advanceAlbum(step){if(!albumPlayer)return;const wasPlaying=albumPlayer.playRequested&&(!$('#album-audio').paused||$('#album-audio').ended);const current=albumPlayer.index;await startAlbumAt(current<0?(step<0?albumPlayer.queue.length-1:0):current+step,wasPlaying,step<0?-1:1)}

async function toggleAlbum(){if(!albumPlayer)return;const audio=$('#album-audio');if(!audio.paused){albumPlayer.playRequested=false;audio.pause();markAlbumTrack();return}if(albumPlayer.index<0){albumPlayer.failed.clear();await startAlbumAt(0);return}$$('audio').forEach(a=>{if(a!==audio)a.pause()});albumPlayer.playRequested=true;try{await audio.play();markAlbumTrack()}catch(error){if(error.name==='NotAllowedError')toast('Press the album cover to play');else{albumPlayer.failed.add(albumPlayer.index);await startAlbumAt(albumPlayer.index+1)}}}

// Keep maintenance selection explicit while searching title, artist, album or ID.
let maintenanceMatches=[];
function maintenancePicker(){return `<label for="maintenance-query">Find a song</label><div class="search-form maintenance-search"><input id="maintenance-query" type="search" autocomplete="off" aria-label="Find song by title, artist, album or ID" placeholder="Title, artist, album or #ID…"><button type="button" data-maintenance-first aria-label="Select first matching song">↵</button></div><div id="maintenance-results" class="maintenance-results"></div><small class="maintenance-count" id="maintenance-count" role="status"></small><input id="stats-song" name="song_id" type="hidden"><div id="maintenance-selected" class="maintenance-selected" hidden></div>`}
function renderMaintenanceMatches(){const query=normal($('#maintenance-query').value),idQuery=/^#\d+$/.test(query)?Number(query.replace('#','')):null;maintenanceMatches=songs.filter(s=>!query||(idQuery!==null?s.id===idQuery:normal([s.title,s.artist,s.album,'#'+s.id].join(' ')).includes(query)));const selected=Number($('#stats-song').value);$('#maintenance-results').innerHTML=maintenanceMatches.slice(0,12).map(s=>`<button class="maintenance-result" type="button" data-maintenance-song="${s.id}" aria-pressed="${s.id===selected}">${compactArt(s)}<span class="compact-copy"><strong>${esc(s.title)}</strong><small>${esc(s.artist)} · ${esc(s.album)}</small></span><small>#${s.id}</small></button>`).join('')||'<div class="empty">No matching songs</div>';$('#maintenance-count').textContent=maintenanceMatches.length+' matches'+(maintenanceMatches.length>12?' · First 12 shown':'')}
function selectMaintenanceSong(id){const s=byId(songs,id);if(!s)return;$('#stats-song').value=s.id;const node=$('#maintenance-selected');node.hidden=false;node.innerHTML=`${compactArt(s)}<div class="compact-copy"><strong>${esc(s.title)}</strong><small>${esc(s.artist)} · ${esc(s.album)} · #${s.id}</small><small>${Math.round(s.elo_score)} Elo · ${s.attempts} trivia attempts · ${s.correct} points</small></div>`;if($('#field-elo'))$('#field-elo').value=Math.round(s.elo_score);if($('#field-attempts')){$('#field-attempts').value=s.attempts;$('#field-correct').value=s.correct}$$('[data-maintenance-song]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.maintenanceSong)===s.id)));$('#editor-submit').disabled=false;if($('[data-clear-trivia]'))$('[data-clear-trivia]').disabled=false}

let tournamentRows=[],tournamentSort='overall';
const tournamentCategories=[['overall','Overall'],['points','Points'],['winrate','Win Rate'],['titles','Championships'],['appearances','Appearances']];
function tournamentMetric(s){return tournamentSort==='points'?Number(s.tournament_points).toFixed(2):tournamentSort==='winrate'?Math.round(s.win_rate)+'%':tournamentSort==='titles'?s.championships:tournamentSort==='appearances'?s.tournaments_entered:Number(s.tournament_points).toFixed(2)}
function renderTournamentLeaders(){
 const eligible=tournamentRows.filter(s=>tournamentSort==='winrate'?s.matches_played>0:(s.tournaments_entered>0||s.matches_played>0||s.championships>0));
 const overall=(a,b)=>b.championships-a.championships||b.tournament_points-a.tournament_points||(b.win_rate??-1)-(a.win_rate??-1)||b.tournaments_entered-a.tournaments_entered||a.title.localeCompare(b.title);
 const key={points:'tournament_points',winrate:'win_rate',titles:'championships',appearances:'tournaments_entered'}[tournamentSort];eligible.sort((a,b)=>(key?Number(b[key])-Number(a[key]):0)||overall(a,b));
 const metricLabel=tournamentSort==='overall'?'Points':tournamentCategories.find(([key])=>key===tournamentSort)[1];
 const render=(rows)=>rows.map((s,i)=>`<a class="compact-track" href="${urlFor('songs',s)}"><span class="compact-rank">${i+1}</span>${compactArt(s)}<span class="compact-copy"><strong>${esc(s.title)}</strong><small>${esc(s.artist)} · ${s.matches_won}W / ${s.matches_lost}L · ${s.tournaments_entered} entries · ${s.championships} titles</small></span><span class="compact-score"><b>${tournamentMetric(s)}</b><small>${metricLabel}${s.win_rate===null?'':' · '+Math.round(s.win_rate)+'% wins'}</small></span></a>`).join('')||'<div class="empty">No results yet</div>';
 $('#tournament-top').innerHTML=render(eligible.slice(0,10));$('#tournament-bottom').innerHTML=render([...eligible].reverse().slice(0,10));$('#tournament-results-count').textContent=eligible.length+' eligible tracks';$$('[data-tournament-sort]').forEach(b=>{b.classList.toggle('active',b.dataset.tournamentSort===tournamentSort);b.setAttribute('aria-pressed',String(b.dataset.tournamentSort===tournamentSort))})
}
async function renderTournamentStats(){
 const [stats,archive]=await Promise.all([api('/api/tournament_stats'),api('/api/tournaments')]);tournamentRows=stats.songs||[];const tournaments=archive.tournaments||[];
 main.innerHTML=`<div class="page-head"><h1 class="tournament">Tournament Stats</h1><a class="btn" href="/tournament">Play Tournament →</a></div><div class="stats">${stat('Tournaments',tournaments.length,'tournament')}${stat('Completed',tournaments.filter(t=>t.status==='completed'||t.champion_id).length,'tournament')}${stat('Tracks with Results',tournamentRows.filter(s=>s.matches_played>0).length,'tournament')}${stat('Championships',tournamentRows.reduce((n,s)=>n+s.championships,0),'tournament')}</div><div class="section-head tournament-category"><div class="pill-nav" aria-label="Tournament category">${tournamentCategories.map(([key,title])=>`<button class="pill ${key===tournamentSort?'active':''}" data-tournament-sort="${key}" aria-pressed="${key===tournamentSort}">${title}</button>`).join('')}</div><small id="tournament-results-count" role="status"></small></div><div class="stats-columns"><section class="panel tournament-panel"><div class="section-head"><h2 class="tournament">Top Tracks</h2><small>Up to 10</small></div><div id="tournament-top"></div></section><section class="panel tournament-panel"><div class="section-head"><h2 class="tournament">Bottom Tracks</h2><small>Up to 10</small></div><div id="tournament-bottom"></div></section></div><section class="tournament-archive"><div class="section-head"><h2 class="tournament">Bracket History</h2></div><div id="tournament-list">${tournaments.map(t=>{const champ=byId(songs,t.champion_id);return `<article class="archive-card" id="tournament-${t.id}"><div class="archive-head"><span class="big tournament">${champ?'🏆':'⚔️'}</span><div><strong>${t.size||'?'}-song tournament #${t.id}${champ?' · '+esc(champ.title):''}</strong><small>${esc(t.scope_type||'global')} · ${esc((t.completed_at||t.created_at||t.timestamp||'').slice(0,10))} · ${t.matches_completed||0} / ${t.matches_created||0} matches</small></div><span class="badge tournament">${esc((t.status||'legacy').replaceAll('_',' '))}</span><button class="btn small" data-tournament="${t.id}" aria-controls="bracket-${t.id}" aria-expanded="false">View bracket</button></div><div class="bracket-detail" id="bracket-${t.id}" hidden></div></article>`}).join('')||'<div class="empty">No tournaments yet</div>'}</div></section>`;
 renderTournamentLeaders();const selected=Number(new URLSearchParams(location.search).get('tournament'));if(selected&&$(`[data-tournament="${selected}"]`))await toggleBracket(selected,$(`[data-tournament="${selected}"]`));
}
async function toggleBracket(id,button){const panel=$('#bracket-'+id);if(!panel)return;panel.hidden=!panel.hidden;button.textContent=panel.hidden?'View bracket':'Hide bracket';button.setAttribute('aria-expanded',String(!panel.hidden));if(panel.hidden||panel.dataset.loaded)return;panel.innerHTML='<div class="empty">Loading bracket…</div>';try{const data=await api('/api/tournaments/'+id),entries=new Map((data.entries||[]).map(e=>[Number(e.id),e])),rows=data.matches||[],rounds=[...new Set(rows.map(m=>Number(m.round_number||1)))].sort((a,b)=>a-b);panel.innerHTML=rows.length?rounds.map(round=>`<div class="bracket-round"><h3>${round===rounds.at(-1)?'Final':'Round '+round}</h3>${rows.filter(m=>Number(m.round_number||1)===round).map(m=>{const side=id=>{const s=entries.get(Number(id))||byId(songs,id);return id?`<a class="${m.winner_id===id?'song':'muted'}" href="/song/${Number(id)}">${esc(s?.title||'Song #'+id)}</a>`:'<span class="muted">Awaiting qualifier</span>'};return `<div class="bracket-match">${side(m.song1_id)}<span class="vs-small">VS</span>${side(m.song2_id)}<small>${m.status==='completed'?`Winner: ${esc(entries.get(Number(m.winner_id))?.title||byId(songs,m.winner_id)?.title||'Unknown')} · ${Number(m.points_awarded||0).toFixed(2)} points`:'Awaiting match'}</small></div>`}).join('')}</div>`).join(''):'<div class="empty">Detailed rounds were not recorded for this bracket.</div>';panel.dataset.loaded='true'}catch(error){panel.innerHTML='<div class="empty error">'+esc(error.message)+'</div>'}}
function filterGlobalHistory(){const rows=$$('#all-history [data-match-mode]');rows.forEach(row=>row.hidden=historyFilter!=='all'&&row.dataset.matchMode!==historyFilter);$('#history-empty').hidden=rows.some(row=>!row.hidden);$$('[data-history]').forEach(b=>{b.classList.toggle('active',b.dataset.history===historyFilter);b.setAttribute('aria-pressed',String(b.dataset.history===historyFilter))})}

// Tournaments use the same two-card layout and audio behaviour as Standard Vote.
let bracketState=null,bracketVoting=false,bracketLoading=false,bracketReveal=null;
async function renderTournamentSetup(){
 document.body.classList.add('tournament-game');main.classList.remove('narrow');
 main.innerHTML=`<div class="page-head"><h1 class="tournament">Tournament</h1><a class="tournament" href="/tournament_stats">Stats & brackets ↗</a></div><section class="panel tournament-setup"><form id="tournament-setup"><div class="form-grid"><div class="field"><label for="t-size">Tournament size</label><select id="t-size"><option value="8">8 tracks</option><option value="16">16 tracks</option><option value="32">32 tracks</option></select></div><div class="field"><label for="t-scope">Scope</label><select id="t-scope"><option value="global">Global</option><option value="artist">Artist</option><option value="album">Album</option></select></div></div><div class="field" id="artist-select-group" hidden><label for="t-artist">Artist</label><select id="t-artist">${artists.map(a=>`<option value="${a.id}">${esc(a.name)} · ${a.song_count} tracks</option>`).join('')}</select></div><div class="field" id="album-select-group" hidden><label for="t-album">Album</label><select id="t-album">${albums.filter(properAlbum).map(a=>`<option value="${a.id}">${esc(a.title)} · ${a.song_count} tracks</option>`).join('')}</select></div><div class="checkboxes"><label><input type="checkbox" id="t-blind">Blind mode</label></div><button class="btn primary" id="generate-btn" type="submit">Generate Bracket →</button><p class="tournament-error" id="setup-error" role="alert" hidden></p></form></section><section class="panel spaced-panel" id="saved-tournaments" hidden><div class="section-head"><h2 class="tournament">Continue a Tournament</h2></div><div id="saved-tournament-list"></div></section>`;
 try{const data=await api('/api/tournaments'),active=(data.tournaments||[]).filter(t=>t.status==='in_progress');$('#saved-tournaments').hidden=!active.length;$('#saved-tournament-list').innerHTML=active.map(t=>`<div class="saved-bracket"><div><strong>Tournament #${t.id}</strong><small>${t.size} tracks · ${t.is_blind?'Blind':'Non-blind'} · ${esc(t.scope_type)} · ${t.matches_completed||0} saved matches</small></div><button class="btn small" type="button" data-resume-tournament="${t.id}">Resume →</button></div>`).join('')}catch(error){$('#saved-tournaments').hidden=false;$('#saved-tournament-list').innerHTML='<div class="empty error">'+esc(error.message)+'</div>'}
 const selected=Number(new URLSearchParams(location.search).get('tournament'));if(selected)await loadBracket(selected);
}
async function generateBracket(){if(bracketLoading)return;bracketLoading=true;const button=$('#generate-btn'),error=$('#setup-error');button.disabled=true;error.hidden=true;try{const scope=$('#t-scope').value,params=new URLSearchParams({size:$('#t-size').value,scope,is_blind:String($('#t-blind').checked)});if(scope!=='global')params.set('scope_id',$(scope==='artist'?'#t-artist':'#t-album').value);const result=await api('/api/generate_bracket?'+params.toString());await loadBracket(result.tournament_id)}catch(err){if($('#setup-error')){$('#setup-error').textContent=err.message;$('#setup-error').hidden=false;button.disabled=false}else toast(err.message)}finally{bracketLoading=false}}
async function loadBracket(id){cancelRoundTransition();stopAudio();const data=await api('/api/tournaments/'+id);bracketState={tournament:data.tournament,tracks:new Map(data.entries.map(s=>[Number(s.id),{...byId(songs,s.id),...s}])),matches:data.matches||[],active:null};bracketReveal=null;bracketVoting=false;history.replaceState(null,'','/tournament?tournament='+data.tournament.id);if(data.tournament.status==='completed'){renderChampion();return}await nextBracketMatch()}
async function nextBracketMatch(){if(!bracketState||bracketVoting)return;cancelRoundTransition();stopAudio();bracketReveal=null;const pending=bracketState.matches.filter(m=>m.status==='pending').sort((a,b)=>a.round_number-b.round_number||a.match_number-b.match_number);if(!pending.length){await completeBracket();return}const current=pending.filter(m=>m.round_number===pending[0].round_number);bracketState.active=current[Math.floor(Math.random()*current.length)];renderBracketMatch()}
function bracketCard(s,i){
 const hidden=!!bracketState.tournament.is_blind&&!bracketReveal,winner=bracketReveal?.winner===s.id,overlay=bracketReveal?(winner?`<div class="score-reveal points-reveal" role="status"><small>Tournament points</small><strong>↑ +<span id="bracket-points">0.00</span></strong><b>🏆 Winner</b></div>`:'<div class="score-reveal runner-up-reveal"><b>Runner-up</b></div>'):'';
 return `<article class="game-card ${winner?'winner':''}">${matchCover(s,'bracket-audio-'+i,hidden,overlay)}<h2>${hidden?'Track '+('AB'[i]):`<a class="song" href="${urlFor('songs',s)}">${esc(s.title)}</a>`}</h2><div class="game-meta">${hidden?'':metadata(s)}</div><button class="btn primary vote-btn" data-tournament-vote="${i}" ${bracketReveal||bracketVoting?'disabled':''}>${bracketReveal?(winner?'✓ Winner':'Runner-up'):'Vote for '+('AB'[i])}</button></article>`;
}
function renderBracketMatch(){
 const {tournament,active,tracks,matches}=bracketState,pair=[tracks.get(active.song1_id),tracks.get(active.song2_id)];if(pair.some(s=>!s)){main.innerHTML='<div class="empty error">A track in this saved match is unavailable.</div><a class="btn" href="/tournament">Back to tournaments</a>';return}
 const inRound=matches.filter(m=>m.round_number===active.round_number),done=inRound.filter(m=>m.status==='completed').length,remaining=tournament.size/2**(active.round_number-1),name=remaining===2?'Grand Final':remaining===4?'Semi-finals':remaining===8?'Quarter-finals':'Round '+active.round_number;
 main.innerHTML=`<div class="game-head"><div><h1 class="tournament">${tournament.is_blind?'Blind Tournament':'Tournament'}</h1><p class="bracket-progress">${name} · Match ${Math.min(done+(bracketReveal?0:1),inRound.length)} / ${inRound.length}</p></div><a class="tournament" href="/tournament_stats?tournament=${tournament.id}">Bracket #${tournament.id} ↗</a></div><div class="matchup">${bracketCard(pair[0],0)}<span class="vs-circle">VS</span>${bracketCard(pair[1],1)}</div>${bracketReveal?roundProgress():''}<p id="bracket-error" class="tournament-error" role="alert" hidden></p>`;attachPlayers()
}
async function voteBracket(index){
 if(bracketVoting||bracketReveal||!bracketState?.active)return;bracketVoting=true;$$('[data-tournament-vote]').forEach(b=>b.disabled=true);stopAudio();const match=bracketState.active,winner=index===0?match.song1_id:match.song2_id,loser=index===0?match.song2_id:match.song1_id;let result;
 try{result=await api('/api/tournament_vote',{tournament_id:bracketState.tournament.id,match_id:match.id,winner_id:winner,loser_id:loser})}catch(error){$('#bracket-error').textContent=error.message;$('#bracket-error').hidden=false;$$('[data-tournament-vote]').forEach(b=>b.disabled=false);return}finally{bracketVoting=false}
 bracketState.matches=result.matches;bracketReveal={winner,points:result.points_awarded};renderBracketMatch();animateScore($('#bracket-points'),0,Number(result.points_awarded),2);scheduleRoundTransition('bracket-audio-'+index,nextBracketMatch);
}
async function completeBracket(){const {tournament,matches}=bracketState,final=[...matches].sort((a,b)=>b.round_number-a.round_number||b.match_number-a.match_number)[0];if(!final?.winner_id){main.innerHTML='<div class="empty error">No final result is available.</div>';return}bracketVoting=true;try{await api('/api/tournament_complete',{tournament_id:tournament.id,champion_id:final.winner_id});tournament.champion_id=final.winner_id;tournament.status='completed';renderChampion()}catch(error){main.innerHTML=`<section class="panel"><h2 class="tournament">Finish Tournament</h2><p class="tournament-error" role="alert">${esc(error.message)}</p><button class="btn primary" data-bracket-next>Retry →</button><a class="btn" href="/tournament">Saved tournaments</a></section>`}finally{bracketVoting=false}}
function renderChampion(){cancelRoundTransition();stopAudio();const {tournament,tracks,matches}=bracketState,s=tracks.get(Number(tournament.champion_id));if(!s){main.innerHTML='<div class="empty">Champion unavailable</div>';return}const wins=matches.filter(m=>m.winner_id===s.id);main.innerHTML=`<div class="page-head"><h1 class="tournament">🏆 Tournament Champion</h1></div><article class="game-card champion-card">${mediaButton(s,'champion-audio',false,true)}<h2><a class="song" href="${urlFor('songs',s)}">${esc(s.title)}</a></h2><div class="game-meta">${metadata(s)}</div><div class="tournament-award"><strong class="tournament">${wins.length} wins</strong><span>${wins.reduce((n,m)=>n+Number(m.points_awarded||0),0).toFixed(2)} points</span></div></article><div class="champion-actions"><a class="btn primary" href="/tournament">Play Again →</a><a class="btn" href="/tournament_stats?tournament=${tournament.id}">View Bracket ↗</a></div>`;attachPlayers()}

