 if(b?.id==='volume-btn'){const panel=$('#volume-panel');panel.hidden=!panel.hidden;b.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden)$('#volume-range').focus()}else if(!e.target.closest('.volume'))volumeClose();
