 if(b.dataset.history){historyFilter=b.dataset.history;if(page==='history')filterGlobalHistory();else renderSongHistory()}
 if(b.dataset.mode&&!voting&&!revealed){stopAudio();blind=b.dataset.mode==='blind';try{localStorage.setItem('votingMode',blind?'blind':'standard')}catch{}await nextMatch()}
