 if(b.dataset.type){searchType=b.dataset.type;searchTag=null;searchLimit=40;renderSearchResults()}
 if(b.hasAttribute('data-more')){searchLimit+=40;renderSearchResults()}
 if(b.dataset.dev){devView=b.dataset.dev;tableQuery='';tableFilters={};tablePage=0;tableSort='id';renderDevView()}
