 if(b.hasAttribute('data-table-next')){tablePage++;renderTableBody()}
 if(b.dataset.edit)editRecord(b.dataset.edit,Number(b.dataset.id));
 if(b.dataset.delete)deleteRecord(b.dataset.delete,Number(b.dataset.id));
