 if(b.dataset.tool)await tool(b.dataset.tool);
 if(b.dataset.songStats){await tool('Trivia maintenance');selectMaintenanceSong(b.dataset.songStats)}
 if(b.dataset.deleteTournament){toolTarget={name:'Delete tournament',id:Number(b.dataset.deleteTournament)};editTarget=null;openDialog('Delete tournament #'+toolTarget.id,'','Delete')}
 if(b.dataset.bracket){const id=Number(b.dataset.bracket),t=byId(DB.tournaments,id),ms=DB.tournament_matches.filter(m=>m.tournament_id===id);toolTarget=null;editTarget=null;openDialog('Tournament #'+id,`<div class="health-row"><span>${t.size} songs</span><strong class="tournament">${esc(byId(songs,t.champion_id)?.title||t.status)}</strong></div>`+ms.map(m=>`<div class="health-row"><span>R${m.round_number} · ${esc(byId(songs,m.song1_id)?.title||'—')} / ${esc(byId(songs,m.song2_id)?.title||'—')}</span><strong class="song">${esc(byId(songs,m.winner_id)?.title||'Pending')}</strong></div>`).join(''),'Done')}
